            innerSizes={innerSizes}
            innerColor={innerColor}
            opacities={opacities}
            shadowColor={shadowColor}
            shadowBlur={shadowBlur}
            shadowOffsetX={shadowOffsetX}
            shadowOffsetY={shadowOffsetY}
            fastDuration={fastDuration}
            slowDuration={slowDuration}
            zIndex={zIndex}
          />
