    },
    {
      name: "ballCount",
      type: "number",
      default: "15",
      description: "Number of metaballs rendered."
    },
    {
      name: "clumpFactor",
      type: "number",
      default: "1",
      description: "Determines how close together the balls are rendered."
    },
    {
      name: "cursorBallSize",
      type: "number",
      default: "3",
      description: "Size of the cursor-controlled ball."
    },
    {
      name: "cursorBallColor",
      type: "string",
      default: "#ff0000",
      description: "Color of the cursor ball."
    }
  ];

  return (
    <TabbedLayout>
      <PreviewTab>
        <Box position="relative" className="demo-container" h={500} p={0} overflow="hidden">
          <MetaBalls
            color={color}
            cursorBallColor={cursorBallColor}
            cursorBallSize={cursorBallSize}
            ballCount={ballCount}
            animationSize={animationSize}
            enableMouseInteraction={enableMouseInteraction}
            hoverSmoothness={hoverSmoothness}
            clumpFactor={clumpFactor}
            speed={speed}
          />
        </Box>

        <Customize className="preview-options">
          <Flex gap={4} align="center" mt={4}>
            <Text fontSize="sm">Color</Text>
            <Input
              type="color"
              value={color}
              onChange={(e) => { setColor(e.target.value); setCursorBallColor(e.target.value) }}
              width="50px"
            />
          </Flex>

          <PreviewSlider
            title="Ball Count"
            min={2}
            max={30}
            step={1}
            value={ballCount}
            onChange={(val) => setBallCount(val)}
            width={150}
          />

          <PreviewSlider
            title="Speed"
            min={0.1}
            max={1}
            step={0.1}
            value={speed}
            onChange={(val) => setSpeed(val)}
            width={150}
          />

          <PreviewSlider
            title="Size"
            min={10}
            max={50}
            step={1}
            value={animationSize}
            onChange={(val) => setAnimationSize(val)}
            width={150}
          />

          <PreviewSlider
            title="Clump Factor"
            min={0.1}
            max={2}
            step={0.1}
            value={clumpFactor}
            onChange={(val) => setClumpFactor(val)}
            width={150}
          />

          <PreviewSwitch
            title="Follow Cursor"
