      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={metaBalls} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...metaBalls} />
      </CliTab>
    </TabbedLayout>
  );
};

export default MetaBallsDemo;

