          </Flex>

          <PreviewSlider
            title="Thickness"
            min={1}
            max={60}
            step={1}
            value={baseThickness}
            onChange={setBaseThickness}
          />

          <PreviewSlider
            title="Speed"
            min={0.3}
            max={0.7}
            step={0.01}
            value={speedMultiplier}
            onChange={setSpeedMultiplier}
          />

          <PreviewSlider
            title="Max Age"
            min={300}
            max={1000}
            step={100}
            value={maxAge}
            onChange={setMaxAge}
          />

          <PreviewSwitch
            title="Enable Fade"
            isChecked={enableFade}
            onChange={(checked) => setEnableFade(checked)}
          />

          <PreviewSwitch
            title="Enable Waves"
            isChecked={enableWaves}
            onChange={(checked) => setEnableWaves(checked)}
          />
        </Customize>

        <PropTable data={propData} />
        <Dependencies dependencyList={['ogl']} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={ribbons} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...ribbons} />
      </CliTab>
    </TabbedLayout>
  );
};

export default RibbonsDemo;

